const item = $input.first();

// n8n Webhook v2 kann body direkt in item.json oder in item.json.body legen
const data = (item.json && item.json.pdfContent) ? item.json
           : (item.json && item.json.body && item.json.body.pdfContent) ? item.json.body
           : item.json;

// Wenn base64 pdfContent von ai_extract_worker kommt
if (data.pdfContent) {
  const base64 = data.pdfContent;
  const name = data.pdfName || 'rechnung.pdf';
  const binaryData = await this.helpers.prepareBinaryData(
    Buffer.from(base64, 'base64'),
    name,
    'application/pdf'
  );
  return [{
    json: {
      emailFrom: data.emailFrom || '',
      emailSubject: data.emailSubject || ''
    },
    binary: { data: binaryData }
  }];
}

// Wenn direkt ein PDF binary reinkommt (curl Test)
const binaryKeys = Object.keys(item.binary || {});
if (binaryKeys.length > 0) {
  return [{
    json: { emailFrom: '', emailSubject: '' },
    binary: { data: item.binary[binaryKeys[0]] }
  }];
}

// Debug: was haben wir bekommen?
throw new Error('Kein PDF gefunden. Empfangene Keys: ' + JSON.stringify(Object.keys(data || {})));

const raw = $input.first().json.content?.parts?.[0]?.text
         || $input.first().json.text
         || JSON.stringify($input.first().json);

let parsed;
try {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  return [{
    json: {
      extractionSuccess: false,
      error: 'JSON parse failed: ' + e.message,
      rawOutput: raw,
      needsManualReview: true
    }
  }];
}

// Plausibilitätsprüfung
let lineItemsSum = 0;
if (parsed.lineItems && parsed.lineItems.length > 0) {
  lineItemsSum = parsed.lineItems.reduce((acc, item) => acc + (item.totalPrice || 0), 0);
}
const amountMatches = parsed.amount
  ? Math.abs(lineItemsSum - parsed.amount) < 0.10
  : true;

const requiredFields = ['vendor', 'amount', 'dueDate', 'invoiceName'];
const missingFields = requiredFields.filter(
  f => parsed[f] === null || parsed[f] === undefined || parsed[f] === ''
);
const isComplete = missingFields.length === 0;
const confidence = parsed.confidence || 0;
const needsManualReview = !isComplete || confidence < 0.85 || !amountMatches;

// Auf Camunda-Format mappen
const lineItems = (parsed.lineItems || []).map(item => ({
  beschreibung: item.description || null,
  menge:        item.quantity    || null,
  einheit:      item.unit        || null,
  einzelpreis:  item.unitPrice   || null,
  steuer_prozent: item.taxRate   || 19,
  netto:        item.totalPrice  || null,
  steuer:       item.totalPrice ? Math.round(item.totalPrice * (item.taxRate || 19) / 100 * 100) / 100 : null,
  brutto:       item.totalPrice ? Math.round(item.totalPrice * (1 + (item.taxRate || 19) / 100) * 100) / 100 : null,
}));

const firstItem = lineItems[0] || {};

return [{
  json: {
    extractionSuccess: true,
    needsManualReview,
    isComplete,
    missingFields,
    confidence,
    plausibilityCheck: {
      lineItemsSum: Math.round(lineItemsSum * 100) / 100,
      amountFromInvoice: parsed.amount,
      matches: amountMatches
    },
    inputChannel: 'ai',
    aiExtracted: true,
    extractionConfidence: confidence,
    customerName:  parsed.vendor          || 'Unbekannter Lieferant',
    invoiceId:     parsed.invoiceName     || null,
    issueDate:     parsed.invoiceDate     || null,
    zahlungsziel:  parsed.dueDate         || null,
    kundennummer:  parsed.customerNumber  || null,
    iban:          parsed.iban            || null,
    totalAmount:   parsed.amount          || 0,
    currency:      parsed.currency        || 'EUR',
    rechnungstyp:  'sonstiges',
    lineItems,
    positionen: lineItems,
    beschreibung:   firstItem.beschreibung   || null,
    menge:          firstItem.menge          || null,
    einheit:        firstItem.einheit        || null,
    einzelpreis:    firstItem.einzelpreis    || null,
    steuer_prozent: firstItem.steuer_prozent || 19,
    netto:          firstItem.netto          || null,
    steuer:         firstItem.steuer         || null,
    brutto:         firstItem.brutto         || null,
    betrag:         firstItem.brutto         || null,
  }
}];
